/* TNM World Wrestling Report: NJPW (New Japan Pro Wrestling).
   Everything the site shows for this promotion lives in this file. */

P.njpw = {"short": "NJPW", "name": "New Japan Pro Wrestling", "home": "Tokyo", "c": "var(--njpw)", "asOf": "1991-07-14", "status": "Six nights into Summer Crush '91. In Hiroshima the Samoans beat down Hirata after Afa cost them the main event, Mutoh & Chono went **** against Fujinami & Koshinaka, and Pegasus Kid hurt his neck two weeks before his Sumo Hall title shot. Hashimoto no-showed.", "stat": ["$368,600", "gate, 5 nights"], "titles": [["IWGP Heavyweight", "Riki Chōshu", "Defenses: Bigelow (Korakuen 7/4, *****), Rotunda (Osaka 7/6). Vs. Chono at Sumo Hall 7/30."], ["IWGP Tag Team", "Hirata & Hashimoto", "Won the belts from Hase & Sasaki in Niigata 7/5, a night after losing to them."], ["IWGP Junior Heavyweight", "Jushin Liger", "Defended vs. El Samurai (Niigata 7/5, ***3/4). Rematch vs. Samurai at Sumo Hall 7/30, replacing the injured Pegasus Kid."]], "factions": [["Mutoh & Chono", "Keiji Mutoh and Masahiro Chono, now billed as a team. Chono gets Chōshu at Sumo Hall."], ["Hase & Sasaki", "Hiroshi Hase and Kensuke Sasaki. Former tag champions."], ["The Samoans", "Samu & Kokina, with Afa (not on the roster) in the corner."], ["The Foreign Crew", "Bigelow (signed 7/4), Scott Norton, Tony Halme, Corporal Kirchner, Ken Patera, Tiger Jeet Singh and the Hart family."]], "stories": [["Chōshu vs. Bigelow", "The tour opened with the IWGP champion beating Bam Bam Bigelow with the lariato in 25:55. *****. Bigelow signed with New Japan the same night."], ["Chono's Moment", "Chōshu called out Chono for Sumo Hall. Chono answered by rolling him up in Niigata and making Halme tap to the STF on TV. In Abashiri he made Hase tap to the STF too, then looked into the crowd and said \"Sumo Hall.\" In Hiroshima Mutoh & Chono beat Fujinami & Koshinaka, ****."], ["New Tag Champions", "Hase & Sasaki beat Hirata & Hashimoto on 7/4. Hirata & Hashimoto took the belts back on 7/5. Hashimoto lost his temper the next night."], ["Liger vs. El Samurai", "Pegasus Kid was set to challenge Liger at Sumo Hall but hurt his neck in Hiroshima and is off the tour. El Samurai, who lost to Liger in Niigata on 7/5, gets the title match instead. Samurai builds through Fukuoka, the Sapporo TV taping and Sendai before facing off with Liger in Morioka."], ["Kim Duk Can't Lose", "Five nights, five wins, including a 55:59 eight-man in Niigata that went ****3/4."], ["Mando and Vega", "Savio Vega has been calling Mando Guerrero \"abuelo\" since Osaka. In Abashiri, Mando tripped him in the opener and cost him the match against Tenzan."], ["The Samoans Arrive", "Samu & Kokina squashed Chōshu and Hiro Saito in 2:26 in Nagoya. Chōshu was helped out holding his ribs. In Abashiri, Afa went after Hirata during the main event, and the tag champions offered the Samoans a title shot in the closing promo. In Hiroshima Afa cost them the main by DQ, and Samu & Kokina beat down Hirata afterward."], ["Inoki and Mutoh", "The founder and the next ace stared each other down in Niigata."], ["The Commuters", "Liger, Pillman, Rotunda and the Blue Blazer all worked New Japan on nights they were also booked in America."], ["The G1 Climax", "New Japan's first G1 Climax tournament is coming in August."]], "desk": ["Pegasus Kid written off the tour; El Samurai replaces him vs. Liger at Sumo Hall 7/30, finish TBD (Sean, 2026-11-12). Rebooked: Samurai d. Honaga (Fukuoka 7/18), Samurai d. Hamada with the title match announced (Sapporo TV 7/19), Hamada d. Mando Guerrero (Sendai 7/22), Liger & Kobayashi vs. Samurai & Honaga with a Liger–Samurai face-off (Morioka 7/29).", "Shinya Hashimoto no-showed Hiroshima 7/14 (Tenzan replaced him in the main). He defends the tag titles on Sapporo TV 7/19.", "Mando Guerrero interfered against Savio Vega 7/13 (unplanned). They're partners on the Sapporo TV plan 7/19.", "Goto beat Aoyagi clean 7/13; the Fukuoka 7/18 DQ win for Aoyagi may become a pinfall.", "Keep Liger, Pillman, Owen (Blazer) and Rotunda (IRS) off NJPW cards while they have U.S. dates. Nights 1–4 stand as run.", "Liger vs. Pegasus Kid at Sumo Hall 7/30 depends on Liger being clear of WCW dates.", "Hiro Saito worked twice in Nagoya (matches 3 and 5).", "Afa interfered 7/5 but isn't on the roster.", "Masanobu Fuchi released 7/5. AJPW only.", "G1 Climax: dates, venue and field to set.", "Gran Hamada confronted Liger 7/4. Loose thread."], "roster": [["Antonio Inoki", "Founder"], ["Tatsumi Fujinami", ""], ["Riki Chōshu", "IWGP Heavyweight Champion"], ["Masahiro Chono", "w/ Mutoh · Sumo Hall vs. Chōshu · STF on Hase 7/13"], ["Keiji Mutoh", "w/ Chono"], ["Shinya Hashimoto", "IWGP Tag Champion · No-show 7/14"], ["Junji Hirata", "IWGP Tag Champion"], ["Hiroshi Hase", "w/ Sasaki"], ["Kensuke Sasaki", "w/ Hase"], ["Shiro Koshinaka", ""], ["Kengo Kimura", ""], ["Osamu Kido", "Pinned Pegasus Kid 7/10"], ["Hiro Saito", ""], ["Hiroyoshi Tenzan", ""], ["Masashi Aoyagi", ""], ["Tarzan Goto", ""], ["Kim Duk", "5–0 on the tour"], ["Jushin Liger", "IWGP Junior Champion · also WCW"], ["Pegasus Kid", "INJ:Neck (7/14). Written off the rest of Summer Crush"], ["El Samurai", "Sumo Hall vs. Liger (IWGP Junior Title)"], ["Norio Honaga", ""], ["Akira Nogami", ""], ["Kuniaki Kobayashi", ""], ["Brian Pillman", "Also WCW"], ["Gran Hamada", "Confronted Liger 7/4"], ["Mando Guerrero", "Feuding with Savio Vega"], ["The Blue Blazer", "Owen Hart · also WWF"], ["Bam Bam Bigelow", "Signed 7/4 · also TWA"], ["Big Van Vader", "Also WCW"], ["Scott Norton", ""], ["Tony Halme", "Three straight losses · 0–4 on the tour"], ["Sting 1992", "WCW's Sting · also WCW"], ["Mike Rotunda", "IRS in the WWF"], ["Jim Neidhart", ""], ["Keith Hart", ""], ["Corporal Kirchner", ""], ["Jeff Gaylord", ""], ["Ken Patera", ""], ["Kokina", "The Samoans"], ["Samu", "The Samoans"], ["Savio Vega", "Feuding with Mando Guerrero"], ["El Gigante", "Also WCW"], ["Tiger Jeet Singh", ""], ["Dos Caras", ""], ["Mil Mascaras", ""]], "departures": [["Masanobu Fuchi", "Released after 7/5. Stays with AJPW."], ["Pegasus Kid", "Neck injury in Hiroshima 7/14. Off the rest of Summer Crush '91, including the Sumo Hall title match."]]};

E.push(...[{"d": "1991-07-04", "p": "njpw", "link": "SUMMER_C", "city": "Tokyo", "venue": "Korakuen Hall", "type": "Summer Crush '91, Night 1 (TV Asahi)", "gate": "1,750 · $56,000", "rate": "***1/4", "m": [["IWGP Tag: Hase & Sasaki (c) vs. Hirata & Hashimoto", "Sasaki submits Hirata (Power Special). Champions retain", "***"], ["Mil Mascaras, Blue Blazer & Keith Hart vs. Halme, Nogami & Pillman", "Mascaras pins Pillman (flying bodypress)", "***1/4"], ["Pegasus Kid vs. El Samurai", "Kid (dragon suplex), 0:32", "*"], ["Jushin Liger vs. Mando Guerrero", "Liger (moonsault). Gran Hamada confronts Liger after", "***1/2"], ["Captain's rules, 2/3 falls: Kim Duk, Patera, Mutoh & Gaylord vs. Saito, El Gigante, Tenzan & Fuchi", "Duk's team, 2–0", "**1/4"], ["Inoki, Dos Caras & Kirchner vs. Chono, Tiger Jeet Singh & Norton", "Kirchner submits Chono (Fujiwara armbar), 33:50", "***"], ["IWGP Heavyweight: Riki Chōshu (c) vs. Bam Bam Bigelow", "Chōshu retains (Riki lariato), 25:55", "*****"]], "n": ["Bigelow signs with New Japan.", "Chōshu announces the first G1 Climax for August and calls out Chono for Sumo Hall.", "WCW and NJPW announce a working relationship."]}, {"d": "1991-07-05", "p": "njpw", "link": "SUMMER-1", "city": "Niigata", "venue": "City Gymnasium", "type": "Night 2", "gate": "2,800 · $61,600", "rate": "***1/4", "m": [["Keith Hart, Blue Blazer & Neidhart vs. Norton, Vega & Gaylord", "Keith Hart beats Vega by count-out, 31:48", "*3/4"], ["Mutoh & Bigelow vs. Inoki & Kirchner", "Bigelow pins Kirchner. Inoki–Mutoh stare-down after", "**1/4"], ["IWGP Tag: Hase & Sasaki (c) vs. Hirata & Hashimoto", "Hirata pins Hase (Machine Suplex). New champions", "**"], ["Samu, Patera, Tenzan & Kim Duk vs. El Gigante, Dos Caras, Guerrero & Fuchi", "Duk pins Dos Caras (power bomb), 55:59. Afa interferes", "****3/4"], ["IWGP Junior: Jushin Liger (c) vs. El Samurai", "Liger retains (moonsault)", "***3/4"], ["Chono & Rotunda vs. Chōshu & Kido", "Chono pins Chōshu (roll-up)", "**1/2"]], "n": ["Chono names Rotunda as Chōshu's next challenger."]}, {"d": "1991-07-06", "p": "njpw", "link": "SUMMER-2", "city": "Osaka", "venue": "Prefectural Gym", "type": "Night 3, World Pro Wrestling TV", "gate": "5,000 · $125,000", "rate": "**1/2", "m": [["Saito, Guerrero & Pegasus Kid vs. Liger, Sasaki & Vega", "Kid beats Vega by DQ, 1:10", "*"], ["Kim Duk & Honaga vs. Hase & Gaylord", "Honaga pins Gaylord (flying elbow), 27:51", "****1/4"], ["Kobayashi & Koshinaka vs. Keith Hart & Patera", "Koshinaka pins Keith Hart (power bomb)", "****1/4"], ["Bigelow & Kirchner vs. Hashimoto & Kimura", "Kirchner beats Hashimoto by DQ", "*1/4"], ["Masahiro Chono vs. Tony Halme", "Chono (STF)", "*1/2"], ["Fujinami, Mutoh & El Samurai vs. Norton, Samu & Pillman", "Mutoh beats Samu by count-out", "**3/4"], ["IWGP Heavyweight: Riki Chōshu (c) vs. Mike Rotunda", "Chōshu retains (Riki lariato)", "**1/2"]], "n": ["Liger vs. Pegasus Kid for the Junior title announced for Sumo Hall.", "Chono flashes the STF sign at the camera."]}, {"d": "1991-07-10", "p": "njpw", "link": "SUMMER-3", "city": "Nagoya", "venue": "Aichi Prefectural Gym", "type": "Night 4", "gate": "4,000 · $100,000", "rate": "***", "m": [["Kido & Kimura vs. Blue Blazer & Pegasus Kid", "Kido pins Kid (side suplex), 35:12", "****"], ["Kuniaki Kobayashi vs. Tony Halme", "Kobayashi (fisherman suplex)", "*1/2"], ["Hase, Sasaki & Liger vs. Saito, Tarzan Goto & Norton", "Liger pins Goto (moonsault)", "***"], ["Kim Duk & Tiger Jeet Singh vs. Fujinami & Koshinaka", "Koshinaka passes out (Tiger Claw)", "***1/2"], ["The Samoans vs. Chōshu & Hiro Saito", "Kokina pins Saito (double splash), 2:26. Chōshu helped out", "**"], ["Mutoh, Chono & Hashimoto vs. Bigelow, Tenzan & Patera", "Hashimoto pins Patera (crucifix)", "***3/4"]]}, {"d": "1991-07-13", "p": "njpw", "city": "Abashiri", "venue": "City Gymnasium", "type": "Night 5", "gate": "2,000 · $26,000", "rate": "**1/2", "m": [["Hiroyoshi Tenzan vs. Savio Vega", "Tenzan (diving headbutt), 9:16. Mando Guerrero interferes", "**1/4"], ["Pegasus Kid vs. Mando Guerrero", "Kid (diving headbutt), 12:06", "***1/2"], ["Tarzan Goto vs. Masashi Aoyagi", "Goto (facebuster), 8:05", "**3/4"], ["Neidhart & Keith Hart vs. Kirchner & Gaylord", "Neidhart pins Gaylord (powerslam)", "*1/4"], ["Tiger Jeet Singh, Kim Duk & Patera vs. Fujinami, Koshinaka & Kido", "Duk pins Kido, 16:01. Singh claws Koshinaka after", "**3/4"], ["Mutoh & Chono vs. Hase & Sasaki", "Chono submits Hase (STF), 22:11", "***3/4"], ["Chōshu, Hirata & Hashimoto vs. The Samoans & Scott Norton", "Chōshu pins Norton (diving lariat), 15:58. Afa interferes against Hirata", "*1/2"]], "n": ["Closing promo: Chōshu tells the Samoans they picked the wrong man; Hashimoto offers them the tag belts.", "Chono to the crowd: \"Sumo Hall.\"", "2,000 at $13; $3,000 merchandise ($1.50 a head). Smallest gate of the tour."]}, {"d": "1991-07-14", "p": "njpw", "city": "Hiroshima", "venue": "Sun Plaza Hall", "type": "Night 6", "ran": 1, "gate": "Attendance TBD", "rate": "**1/4", "m": [["El Samurai vs. Akira Nogami", "Samurai (inverted swinging DDT), 10:06", "*1/2"], ["Hiro Saito & Kengo Kimura vs. Tony Halme & Jeff Gaylord", "Saito pins Halme (back suplex), 10:14. Halme 0–4", "**"], ["Mil Mascaras, Dos Caras & Gran Hamada vs. Mando Guerrero, Norio Honaga & Kuniaki Kobayashi", "Mascaras pins Honaga (flying bodypress), 15:44", "***"], ["Pegasus Kid vs. Osamu Kido", "Kid (diving headbutt), 17:36. Kid hurts his neck", "**1/4"], ["Bam Bam Bigelow & Corporal Kirchner vs. Jim Neidhart & Keith Hart", "Bigelow pins Keith (Greetings from Asbury Park), 12:11", "*3/4"], ["Mutoh & Chono vs. Fujinami & Koshinaka", "Mutoh pins Koshinaka (moonsault), 18:38", "****"], ["Chōshu, Hirata & Tenzan vs. The Samoans & Tarzan Goto", "Hirata by DQ over Samu, 15:07. Afa interferes; Samoans beat down Hirata after", "*"]], "n": ["Shinya Hashimoto no-showed. Tenzan took his place in the main event.", "Pegasus Kid hurt his neck against Kido: out about 8 cards.", "Closing promo: Chōshu helps Hirata up. The Samoans go through him and the champions every night until Sumo Hall.", "Same night as the Bash and WrestleFest (Super Sunday). Attendance and gate not reported."]}, {"d": "1991-07-18", "p": "njpw", "city": "Fukuoka", "venue": "Hakata Star Lanes", "type": "Night 7"}, {"d": "1991-07-19", "p": "njpw", "city": "Sapporo", "venue": "Nakajima Sports Center", "type": "TV taping"}, {"d": "1991-07-22", "p": "njpw", "city": "Sendai", "venue": "Sendai Gymnasium", "type": "Night 9"}, {"d": "1991-07-29", "p": "njpw", "city": "Morioka", "venue": "Iwate Prefectural Gym", "type": "Night 10"}, {"d": "1991-07-30", "p": "njpw", "city": "Tokyo", "venue": "Sumo Hall", "type": "Summer Crush '91 finale", "big": 1, "plan": 1, "m": [["IWGP Heavyweight: Riki Chōshu (c) vs. Masahiro Chono", "", ""], ["IWGP Junior: Jushin Liger (c) vs. El Samurai", "", ""]], "n": ["Liger depends on his WCW dates.", "El Samurai replaces the injured Pegasus Kid."]}]);

Object.assign(ARTICLES, {"njpw-choshu-bigelow": {"p": "njpw", "news": 1, "region": "Japan Report", "by": "Newsletter staff", "date": "1991-07-11", "kicker": "New Japan · Korakuen Hall · July 4", "title": "Chōshu vs. Bigelow", "dek": "New Japan opened Summer Crush '91 with the best match anyone in the world has had this summer. Riki Chōshu kept the IWGP title. Bam Bam Bigelow got a contract.", "body": [["p", "Korakuen Hall on July 4 held 1,750 people in a building built for 1,800, at a $32 average for $56,000. It was the opening night of Summer Crush '91 on TV Asahi, and the main event was Riki Chōshu defending the IWGP Heavyweight Title against Bam Bam Bigelow. Chōshu won with the Riki lariato at 25:55. It was a five-star match."], ["p", "That isn't a number that gets handed out often. Bigelow is the best big-man athlete in the world right now, a 30-year-old who moves like a junior, and Chōshu is a short, stiff, intense champion who works best against somebody he can throw himself into. They went nearly 26 minutes, and the Korakuen crowd, which has seen everything, treated it like something special."], ["h", "Bigelow signs"], ["p", "Afterward New Japan announced that Bigelow has officially signed with the company. That's significant beyond the tour. Bigelow also headlined the debut show of the Tri-State Wrestling Alliance in Philadelphia, a draw with Austin Idol, and he's due back there in August. New Japan clearly sees him as a long-term top foreigner, and on this evidence, they're right."], ["h", "The rest of the night"], ["p", "Chōshu used the microphone to promise a historic tour leading to the first G1 Climax in August, and he called out Masahiro Chono for Sumo Hall on July 30. The undercard was strong: Hase and Sasaki kept the tag titles over Hirata and Hashimoto (***), Liger beat Mando Guerrero (***1/2) and was confronted by Gran Hamada, and Inoki's six-man went 33:50, with Corporal Kirchner making Chono submit to the Fujiwara armbar (***). The card rated ***1/4."], ["p", "Two nights later in Osaka, Chōshu defended again on World Pro Wrestling TV, beating Mike Rotunda with the lariato (**1/2). The Osaka show drew 5,000 for $125,000, the best house of the tour so far. Rotunda, by the way, was booked for WWF in Anaheim as IRS the same night. More on that elsewhere."]], "facts": [["Match", "Chōshu (c) d. Bigelow"], ["Title", "IWGP Heavyweight"], ["Finish", "Riki lariato, 25:55"], ["Rating", "*****"], ["Crowd", "1,750 · $56,000"], ["Next defense", "Chono, Sumo Hall 7/30"]], "factTitle": "The Main Event"}, "njpw-chonos-moment": {"p": "njpw", "news": 1, "region": "Japan Report", "by": "Newsletter staff", "date": "1991-07-11", "kicker": "New Japan · IWGP Heavyweight Title", "title": "Chono's Moment", "dek": "Chōshu called out Masahiro Chono for Sumo Hall. Then Chono pinned him. The champion's biggest problem this summer may be the man he chose.", "body": [["p", "On opening night at Korakuen, Riki Chōshu named his challenger for the Sumo Hall finale on July 30: Masahiro Chono. Chono's first night of the tour hadn't gone well. He submitted to Corporal Kirchner's Fujiwara armbar in the Inoki six-man."], ["p", "In Niigata the next night, Chono and Mike Rotunda beat Chōshu and Osamu Kido when Chono rolled up the champion. It's not a dominant win, and the match was only **1/2, but in New Japan a pin on the IWGP champion before a title match is a statement. In his interview afterward, Chono picked Rotunda as Chōshu's next opponent in Osaka, like a man who's already setting the champion's schedule."], ["h", "The STF"], ["p", "In Osaka on July 6, Chono beat Tony Halme with the STF in 7:18 (*1/2) and then held up the STF hand signal to the TV Asahi camera. The message was for Chōshu. Chono has been building that hold into his signature, and it's the kind of finish New Japan crowds believe can end a title match."], ["p", "In Nagoya on July 10, Chono and Keiji Mutoh were billed as a team for the first time. They and Shinya Hashimoto beat Bigelow, Tenzan and Patera (***3/4) when Hashimoto pinned Patera. Mutoh and Chono together, with Hashimoto in the same corner, is what the next generation of New Japan looks like."], ["h", "The champion"], ["p", "Chōshu, meanwhile, had the worst night of his tour in Nagoya: he and Hiro Saito were squashed by the Samoans in 2:26, and he was helped to the back holding his ribs. If that's the setup, it's a classic one. A hurt champion heading into a title match against a younger challenger who has already pinned him. Sumo Hall holds 11,000. This is the match that has to fill it."]], "facts": [["7/4", "Chōshu calls out Chono"], ["7/5", "Chono pins Chōshu (roll-up)"], ["7/6", "Chono d. Halme (STF), signals at the camera"], ["7/10", "Mutoh & Chono billed as a team"], ["Sumo Hall 7/30", "Chōshu (c) vs. Chono"]], "factTitle": "The Build"}, "njpw-new-tag-champions": {"p": "njpw", "news": 1, "region": "Japan Report", "by": "Newsletter staff", "date": "1991-07-11", "kicker": "New Japan · IWGP Tag Team Title", "title": "New Tag Champions", "dek": "The IWGP tag titles changed hands on the second night of the tour, in a rematch from the night before. Then one of the new champions lost his temper.", "body": [["p", "Hiroshi Hase and Kensuke Sasaki opened Summer Crush as IWGP Tag Team Champions and kept the belts at Korakuen on July 4, when Sasaki made Junji Hirata submit to the Power Special (***). Twenty-four hours later in Niigata, Hirata and Shinya Hashimoto got an immediate rematch and won it, when Hirata pinned Hase with the Machine Suplex at 15:37."], ["p", "The Niigata match was only **, but the booking was quick and clean: champions win, challengers come back angry, challengers win. It's the kind of title change you do on a house show when you want the belts to move without waiting for a big building."], ["h", "Hashimoto"], ["p", "The interesting part came the next night in Osaka. Hashimoto and Kengo Kimura lost to Bigelow and Kirchner when Kirchner beat Hashimoto by DQ. Hashimoto lost his temper and got himself disqualified the night after winning the belts. It's a small thing on a TV show, but it fits who Hashimoto is: the most explosive young heavyweight in the company, someone who can't always control it. That's a character."], ["p", "He was back on track in Nagoya, pinning Ken Patera with a crucifix in the six-man with Mutoh and Chono (***3/4). If New Japan is building a top three for the 1990s out of Mutoh, Chono and Hashimoto, they're doing it in plain sight."], ["h", "What's next"], ["p", "Hase and Sasaki teamed with Liger in Nagoya and won. They'll want the belts back. The Samoans, who just squashed the IWGP champion's team, are the other obvious challengers."]], "facts": [["7/4 Korakuen", "Hase & Sasaki retain, ***"], ["7/5 Niigata", "Hirata & Hashimoto win, **"], ["Finish", "Machine Suplex on Hase"], ["7/6 Osaka", "Hashimoto DQ'd vs. Kirchner"], ["Contenders", "Hase & Sasaki, the Samoans"]], "factTitle": "The Title"}, "njpw-liger-vs-pegasus": {"p": "njpw", "news": 1, "region": "Japan Report", "by": "Newsletter staff", "date": "1991-07-11", "kicker": "New Japan · IWGP Junior Heavyweight Title", "title": "Liger vs. Pegasus Kid", "dek": "The Pegasus Kid beat El Samurai in 32 seconds and got a title shot at Sumo Hall. Then Osamu Kido pinned him. Meanwhile, Liger may have a scheduling problem.", "body": [["p", "Jushin Liger is the IWGP Junior Heavyweight Champion, and he's been as good as ever on this tour. He beat Mando Guerrero at Korakuen (***1/2), kept the belt against El Samurai in Niigata with the moonsault (***3/4), and pinned Tarzan Goto in a six-man in Nagoya (***)."], ["p", "His Sumo Hall challenger is the Pegasus Kid, announced in Osaka. Kid made a big first impression: he beat El Samurai with a dragon suplex in 32 seconds at Korakuen, so fast the trainers came out to check on Samurai. In Osaka he beat Savio Vega by DQ in 1:10. Then, in Nagoya, he and the Blue Blazer lost to Osamu Kido and Kengo Kimura in a 35-minute match that was the best of the night at ****, when Kido pinned him with a side suplex. A loss on the way into a title match isn't ideal, but Kid looked great in it."], ["h", "Hamada"], ["p", "After Liger's win at Korakuen, Gran Hamada came out to the entrance way and stared him down. Nothing has come of it yet. Hamada is a veteran with Mexican experience and a short contract, and the confrontation reads like a door left open for later."], ["h", "The calendar"], ["p", "Here's the issue. Liger is also on the WCW roster, and on this tour he's already worked New Japan on nights when he was booked in America, including Niigata on July 5, the night WCW had him in Philadelphia against Brian Pillman. New Japan's policy going forward is reportedly to keep its American-based talent off cards when they have U.S. dates. That makes Liger vs. Kid at Sumo Hall on July 30 a match that depends on what WCW has him doing that week. If it falls through, Kid needs another opponent, and Hamada is sitting right there."]], "facts": [["Champion", "Jushin Liger"], ["Defense", "d. El Samurai, ***3/4 (7/5)"], ["Challenger", "Pegasus Kid"], ["Kid's tour", "W 0:32, W DQ, L to Kido (****)"], ["Sumo Hall", "7/30, if Liger is free"], ["Loose thread", "Gran Hamada"]], "factTitle": "The Title Picture"}, "njpw-kim-duk-unbeaten": {"p": "njpw", "news": 1, "region": "Japan Report", "by": "Newsletter staff", "date": "1991-07-11", "kicker": "New Japan · The Undercard", "title": "Kim Duk Can't Lose", "dek": "Kim Duk has been on the winning side every night of the tour, including the longest match anyone has had all year, a 56-minute eight-man in Niigata that came within a quarter-star of perfect.", "body": [["p", "The quietest story of Summer Crush is Kim Duk, who is four for four."], ["p", "At Korakuen his team won a captain's-rules, two-out-of-three-falls eight-man 2–0, with Mutoh pinning Hiro Saito. In Osaka, he and Norio Honaga beat Hiroshi Hase and Jeff Gaylord in 27:51 when Honaga hit a flying elbow (****1/4). In Nagoya he and Tiger Jeet Singh beat Tatsumi Fujinami and Shiro Koshinaka when Koshinaka passed out in Singh's Tiger Claw (***1/2)."], ["h", "Niigata"], ["p", "And then there was Niigata on July 5. Samu, Ken Patera, Hiroyoshi Tenzan and Kim Duk against El Gigante, Dos Caras, Mando Guerrero and Masanobu Fuchi, an eight-man that went 55:59. Duk ended it by power-bombing Dos Caras. Afa, who isn't on the roster, interfered against El Gigante. It rated ****3/4."], ["p", "Nobody books a 56-minute eight-man on a Friday house show in Niigata expecting it to be the best match of the night, and it was the best match of almost any night anywhere. It's also the kind of thing that kills a crew for the rest of a tour. Fuchi was released by New Japan after this show and is staying with All Japan, so it was his last NJPW match."], ["h", "The Tiger Claw"], ["p", "Tiger Jeet Singh making Koshinaka pass out is worth noting too. Singh is a throwback attraction, and New Japan crowds know exactly who he is. Using the Claw as a legitimate finish on a former junior champion is a choice, and it makes Singh a threat again for the rest of the tour."], ["p", "Duk himself is a veteran, not a young star, but someone in the office clearly likes having him win. If the streak continues, he's a G1 Climax dark horse."]], "facts": [["7/4", "Captain's team wins, 2–0"], ["7/5", "d. Dos Caras, 55:59, ****3/4"], ["7/6", "w/ Honaga, ****1/4"], ["7/10", "w/ Singh, Tiger Claw, ***1/2"], ["Record", "4–0"]], "factTitle": "The Streak"}, "njpw-samoans": {"p": "njpw", "news": 1, "region": "Japan Report", "by": "Newsletter staff", "date": "1991-07-11", "kicker": "New Japan · Aichi Prefectural Gym, Nagoya · July 10", "title": "The Samoans Arrive", "dek": "Samu and Kokina beat the IWGP Heavyweight Champion's team in two minutes and 26 seconds, and Riki Chōshu was helped to the back holding his ribs.", "body": [["p", "The most shocking result of the tour so far was a 2:26 tag match in Nagoya on July 10. The Samoans, Samu and Kokina, beat Riki Chōshu and Hiro Saito when Kokina pinned Saito with a double splash. Chōshu was helped to the back holding his ribs."], ["p", "Saito took the fall, so Chōshu is protected on paper. But the IWGP Heavyweight Champion being part of a two-minute squash, three weeks before his title defense against Chono, is a deliberate choice. It makes the Samoans look like monsters, and it gives Chōshu a reason to look vulnerable going into Sumo Hall."], ["h", "The family"], ["p", "Samu was already on the winning side of the 56-minute eight-man in Niigata, where Afa, who isn't on the roster, got involved against El Gigante. In Osaka he took the count-out loss to Mutoh in the Fujinami six-man (**3/4). Kokina is huge and on a short deal. With Afa in the corner, they're a unit New Japan can drop into any tag picture."], ["h", "The flag"], ["p", "Hiro Saito, Chōshu's partner in the squash, also worked a six-man earlier on the same card, losing to Hase, Sasaki and Liger. Wrestling twice in a night happens, but it's worth knowing."], ["p", "The Nagoya show drew 4,000 at $25 for $100,000 in a 7,500-seat building and rated ***, the second-best house of the tour."]], "facts": [["Match", "Samoans d. Chōshu & Saito"], ["Time", "2:26"], ["Finish", "Kokina pins Saito (double splash)"], ["Rating", "**"], ["After", "Chōshu helped out, holding ribs"], ["Manager", "Afa (not on roster)"]], "factTitle": "The Squash"}, "njpw-inoki-mutoh": {"p": "njpw", "news": 1, "region": "Japan Report", "by": "Newsletter staff", "date": "1991-07-11", "kicker": "New Japan · Niigata City Gymnasium · July 5", "title": "Inoki and Mutoh", "dek": "Antonio Inoki and Keiji Mutoh stared each other down in Niigata. It wasn't a long moment. It didn't need to be.", "body": [["p", "Antonio Inoki is still New Japan. He founded it, he's still in the ring on this tour, and his six-man on opening night was the second-longest match on the card at 33:50: Inoki, Dos Caras and Corporal Kirchner over Chono, Tiger Jeet Singh and Scott Norton when Kirchner made Chono submit to the Fujiwara armbar (***)."], ["p", "In Niigata, Inoki and Kirchner lost to Keiji Mutoh and Bam Bam Bigelow when Bigelow pinned Kirchner with Greetings from Asbury Park (**1/4). After the bell, Inoki and Mutoh stood in the middle of the ring and stared at each other."], ["h", "Why it matters"], ["p", "Mutoh is the most marketable young wrestler in the company. He spent years in America as the Great Muta, he's a natural star, and he's now billed as a team with Chono. He beat Samu by count-out in Osaka and won the Korakuen eight-man for his side by pinning Hiro Saito with the moonsault. Inoki is the man every young star in New Japan has to be measured against."], ["p", "A stare-down on a house show is a promise, not a program. The likeliest place for it to go is the G1 Climax in August. A tournament is a perfect place to put a founder and an heir in the same bracket without anyone having to say it out loud."], ["h", "Bigelow and Kirchner"], ["p", "The other thing worth noting from that match: Bigelow and Kirchner were opponents in Niigata, then partners the next night in Osaka, where they beat Hashimoto and Kimura by DQ. New Japan's foreigners are being moved around freely. That's normal on a tour, but it means there's no gaijin program yet beyond Bigelow's title shot."]], "facts": [["7/4", "Inoki's team d. Chono's team, 33:50"], ["7/5", "Mutoh & Bigelow d. Inoki & Kirchner"], ["After", "Inoki–Mutoh stare-down"], ["Mutoh", "Now teaming with Chono"], ["Next stage", "G1 Climax, August"]], "factTitle": "The Moment"}, "njpw-the-commuters": {"p": "njpw", "news": 1, "region": "Japan Report", "by": "Newsletter staff", "date": "1991-07-11", "kicker": "New Japan · Backstage", "title": "The Commuters", "dek": "At least four wrestlers worked New Japan's opening week on nights they were also booked in the United States. Nobody has figured out how to be in two places at once.", "body": [["p", "The talent exchange between New Japan and the American promotions has been one of the stories of the summer. WCW and New Japan announced a working relationship on opening night at Korakuen, with Brian Pillman in for the July tour. But a look at the first week's calendar shows a problem."], ["h", "Who was where"], ["p", "Jushin Liger worked NJPW all four nights, including Niigata on July 5 and Osaka on July 6, when WCW had him in Philadelphia against Pillman and on Saturday Night in Atlanta. Pillman himself worked Korakuen on July 4 and Osaka on July 6, with WCW's Philadelphia show in between. Mike Rotunda, who is IRS in the WWF, challenged Chōshu for the IWGP title in Osaka on July 6, the same night he was on the WWF card in Anaheim. Owen Hart, who works New Japan under a mask as the Blue Blazer, was in Korakuen, Niigata and Nagoya on dates wrapped around WWF shows in Calgary and Edmonton."], ["p", "El Gigante worked July 4 and 5 for New Japan and WCW in Atlanta on July 6. That one is at least theoretically possible."], ["h", "The policy"], ["p", "The word is that New Japan has decided to keep its U.S.-based talent off cards while they have American dates, starting now. What already happened stands. The most immediate effect is on Sumo Hall: Liger vs. the Pegasus Kid for the Junior title on July 30 depends on Liger being free, and WCW's July calendar is busy."], ["h", "Others to watch"], ["p", "New Japan's roster also lists Sting, billed as \"Sting 1992,\" and Big Van Vader, both under WCW contracts, though neither has been booked on this tour. Masanobu Fuchi, who worked the first two nights, has been released and is back with All Japan full time. Bam Bam Bigelow, who signed with New Japan on opening night, is also due back with the Tri-State Wrestling Alliance in Philadelphia in August."]], "facts": [["Liger", "NJPW 7/5, 7/6 · WCW 7/5, 7/6"], ["Pillman", "NJPW 7/4, 7/6 · WCW 7/5"], ["Rotunda (IRS)", "NJPW & WWF, both 7/6"], ["Blue Blazer (Owen)", "NJPW 7/10 · WWF 7/9"], ["Policy", "U.S.-based talent off NJPW cards when booked in the U.S."]], "factTitle": "The Calendar"}, "njpw-g1-climax": {"p": "njpw", "news": 1, "region": "Japan Report", "by": "Newsletter staff", "date": "1991-07-11", "kicker": "New Japan · August", "title": "The G1 Climax", "dek": "New Japan is running its first G1 Climax in August. Riki Chōshu called it the payoff to a historic tour. It might be the biggest gamble the company makes this year.", "body": [["p", "On opening night at Korakuen, after beating Bigelow in the match of the summer, Riki Chōshu got on the microphone and announced the first G1 Climax, a heavyweight tournament in August, as the payoff to the Summer Crush tour."], ["p", "No dates, venue or field have been announced yet. What's clear is the idea: a round-robin or bracket tournament of the top heavyweights in the company, held over a short run of big shows. New Japan has done tournaments before, but nothing pitched like this."], ["h", "The field"], ["p", "Look at who is already on this tour and it's easy to sketch. Chōshu, the champion. Chono, his Sumo Hall challenger. Keiji Mutoh, coming off the stare-down with Inoki. Shinya Hashimoto, a new tag champion with a temper. Bigelow, newly signed. Scott Norton. Tatsumi Fujinami. Maybe Big Van Vader or Sting from the WCW relationship. Kim Duk, who hasn't lost all tour, as the dark horse."], ["h", "The gamble"], ["p", "The risk is that a tournament asks people to buy tickets for a field instead of a match. The reward is that it makes stars out of whoever has a good run, and New Japan has three young heavyweights in Mutoh, Chono and Hashimoto who are ready to be made into stars. If one of them wins it, the tournament pays for itself for years."], ["p", "Whatever happens at Sumo Hall on July 30 will shape the field. A Chono win over Chōshu makes the G1 his to lose."]], "facts": [["Announced", "Korakuen, 7/4"], ["When", "August 1991"], ["Format", "Heavyweight tournament (details TBA)"], ["Likely names", "Chōshu, Chono, Mutoh, Hashimoto, Bigelow"], ["Dark horse", "Kim Duk"]], "factTitle": "The Tournament"}, "njpw-observer-notes-0710": {"p": "njpw", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-11", "region": "Japan Report", "kicker": "New Japan · Backstage Notes", "title": "Backstage Notes: Nagoya", "dek": "The Samoans flatten the IWGP champion, and Kim Duk can't lose.", "factTitle": "Filed from", "facts": [["Show", "Nagoya, 7/10"], ["Gate", "4,000 · $100,000"], ["Card", "***"]], "body": [["h", "Nagoya"], ["p", "The Samoans squashed Riki Choshu and Hiro Saito in 2:26, and Choshu was helped to the back holding his ribs three weeks before he defends the IWGP title against Masahiro Chono at Sumo Hall. Kim Duk is 4-for-4 on the tour. Tony Halme has lost three straight."]]}, "njpw-observer-abashiri-0713": {"p": "njpw", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-13", "region": "Japan Report", "kicker": "New Japan · Abashiri · July 13", "title": "Observer: Abashiri", "dek": "Chono makes Hase tap and says \"Sumo Hall.\" Afa goes after Hirata. Mando Guerrero picks a fight nobody booked. And the Kawada rumors point at New Japan.", "factTitle": "Filed from", "facts": [["Show", "Abashiri, 7/13"], ["Gate", "2,000 · $26,000"], ["Merch", "$3,000"], ["Card", "**1/2"], ["Match of the night", "Mutoh & Chono d. Hase & Sasaki, ***3/4"]], "body": [["h", "Abashiri"], ["p", "Summer Crush made its northernmost stop on Saturday, Abashiri on the Hokkaido coast, a town most people in Japan know for its prison. The City Gymnasium seats 2,500 and drew 2,000 at a $13 average for $26,000, plus $3,000 in merchandise. That's the smallest gate and the cheapest ticket of the tour by a distance, which is what a Saturday at the end of the line in Hokkaido gets you. The card came in at ** 1/2, tied with the Osaka TV show for the lowest of the tour, and once again the undercard carried a weak main event."], ["p", "The main event went exactly where it was booked. Riki Choshu, Junji Hirata and Shinya Hashimoto beat the Samoans and Scott Norton when Choshu flattened Norton with a diving lariat at 15:58. It was only * 1/2. Booking note: the plan had the Samoans jumping Choshu after the bell. Instead Afa came off the floor during the match and went after Hirata, the third time in four shows the family has made itself felt. It works fine for the story, since the tag champions are the next target anyway. The show closed with the traditional in-ring promo from the winners. Choshu told the Samoans they picked the wrong fight and the wrong man, and Hashimoto told them the IWGP tag belts are waiting any night they want them. Everything points to the Samoans getting a tag title shot at Sumo Hall."], ["h", "Chono"], ["p", "The match of the night was Keiji Mutoh and Masahiro Chono over Hiroshi Hase and Kensuke Sasaki at *** 3/4, when Chono made Hase submit to the STF at 22:11. It was booked for 18 minutes and went 22, and nobody minded. That's the second STF finish for Chono in three shows. He has now pinned the champion, made Halme tap on TV and made a former tag champion tap tonight, and he looked straight into the crowd and said \"Sumo Hall\" afterward. If New Japan is building Chono into a credible challenger, it's working."], ["h", "The undercard"], ["p", "Tiger Jeet Singh, Kim Duk and Ken Patera beat Tatsumi Fujinami, Shiro Koshinaka and Osamu Kido when Duk pinned Kido at 16:01 (** 3/4). Duk is now 5-0 on the tour. Singh also put the Tiger Claw on Koshinaka after the bell, three nights after making him pass out in it in Nagoya."], ["p", "The Pegasus Kid beat Mando Guerrero with a diving headbutt at 12:06 (*** 1/2), as booked. The Kid is getting the build of a man about to win a title, and Guerrero, a 20-year veteran, made him look like one."], ["p", "Booking note: Tarzan Goto pinned Masashi Aoyagi clean with a facebuster at 8:05 (** 3/4). The plan was a chair shot behind the referee's back to start the feud. It's a cleaner win than intended, which means Aoyagi needs a stronger comeback when they meet again in Fukuoka on 7/18. The DQ win planned there may need to become a pinfall."], ["p", "Booking note: the opener had the night's only real surprise. Hiroyoshi Tenzan pinned Savio Vega with a diving headbutt at 9:16 (** 1/4), but Mando Guerrero, waiting at the entrance for his own match, came down and tripped Vega to set up the finish. Nobody planned that. Mando and Vega are booked as partners against Mil Mascaras and Dos Caras on the Sapporo TV taping on 7/19. Either that match becomes Mando vs. Vega or somebody has to explain the opener."], ["p", "Jim Neidhart and Keith Hart beat Corporal Kirchner and Jeff Gaylord when Neidhart powerslammed Gaylord at 12:55 (* 1/4). Kirchner and Gaylord together don't work."], ["h", "Backstage"], ["p", "Backstage, the biggest New Japan story of the week happened in All Japan. Toshiaki Kawada gave notice to Giant Baba's office today, and his last date is Okayama on Monday. Kawada is angry about being pulled out of the USWA, and the strongest rumor is that he's headed to New Japan. A Kawada jump would be the most serious shot fired between the two companies in years. New Japan's back half runs through Sumo Hall on July 30, so if he's coming, there's room for a debut."], ["p", "Jushin Liger was not in Abashiri. He's at WCW's Great American Bash in Baltimore tomorrow against Brian Pillman, and then he, the Blue Blazer and Mike Rotunda work CMLL in Acapulco on Wednesday. New Japan's rule now keeps its American-based talent off cards when they have U.S. dates."], ["h", "Next"], ["p", "Summer Crush goes to Hiroshima's Sun Plaza Hall on Sunday, the same night as the Bash and WrestleFest. The Samoans and Tarzan Goto face Choshu and the tag champions in the main event."]]}, "njpw-diary-mando-0713": {"p": "njpw", "series": "diary", "by": "Mando Guerrero", "date": "1991-07-13", "place": "Abashiri, Hokkaido", "kicker": "From the Road · Abashiri, July 13", "title": "Who's Finished", "dek": "Mando Guerrero on a prison town in July, Savio Vega's mouth, and the Canadian kid who hits the diving headbutt like Harley Race.", "factTitle": "The Night", "facts": [["Show", "NJPW Summer Crush '91, Night 5"], ["Match", "Pegasus Kid d. Mando Guerrero"], ["Finish", "Diving headbutt, 12:06"], ["Rating", "***1/2"], ["Also", "Tripped Savio Vega in the opener"]], "body": [["p", "They told me Abashiri is famous for its prison. One of the young boys who carries our bags wanted to take me to the museum this morning, to see the old cells. I told him I've spent enough time in buildings with no way out. I've been in this business twenty years."], ["p", "It's July and I can see my breath at night. We came from Nagoya on a plane and then on a bus, and the bus went through so much nothing that I thought we were driving to Russia. The building held two thousand people. Good people. Quiet until something happens, and then they come off their seats like someone lit them on fire."], ["p", "I want to write down what happened in the opener, because I know the office will ask me."], ["p", "Since Osaka, Savio Vega has been running his mouth. He got himself disqualified in our six-man there, and he decided that was my fault, and on the bus he started calling me abuelo. Grandfather. Every day. Old man this, old man that. The Guerreros are finished, he says. My brothers are finished, my nephews will be finished. I let it go for a week. I'm a professional."], ["p", "Tonight I was standing by the curtain waiting for my match, and Vega had the young boy Tenzan in trouble. He went up on the ropes, and he looked right at me before he did it. Smiling. So I walked down and took his foot. That's all. One hand. Tenzan hit him with the headbutt and it was over. The boy doesn't need my help. He's going to be a big star here. But Vega needed a lesson about who's finished."], ["p", "Then I had to go out and wrestle the Pegasus Kid. Twelve minutes. I want to say something about this kid. He's from Canada, he learned in Stu Hart's basement, and he wrestles like every match is the last one he'll ever get. He hit me with the diving headbutt from the top and I saw lights. Harley Race used to hit that move like that. I didn't know anybody else still could."], ["p", "After the match, in the back, he shook my hand and said thank you in Spanish. Bad Spanish. I liked him more for it. He'll be the junior champion before the summer is over, I think. Liger is a great one, but Liger is in America, and this kid is here every night."], ["p", "Tomorrow is Hiroshima. Me, Honaga and Kobayashi against Mil Mascaras, Dos Caras and Gran Hamada. I have known the Mascaras brothers since I was a young man in Los Angeles. They don't like to lose, and Hamada doesn't like anybody. It will be a long night."], ["p", "Back home tomorrow is the Bash. I'll call my brothers when I can find a phone that works with my card. My little brother Eddie is in Mexico City working for CMLL, and he is the best of all of us. Somebody should tell Savio Vega that."]]}, "njpw-hirata-stands-up": {"p": "njpw", "kicker": "New Japan · Summer Crush '91 · Hiroshima, July 14", "title": "The Samoans Leave a Mark", "dek": "Hirata wins by disqualification and pays for it, Mutoh's moonsault drops Koshinaka, and Pegasus Kid beats Kido the hard way.", "by": "By the magazine staff", "date": "1991-07-14", "factTitle": "The Card", "facts": [["Main", "Chōshu, Hirata & Tenzan d. Samoans & Goto (DQ)"], ["Best match", "Mutoh & Chono d. Fujinami & Koshinaka, ****"], ["Hurt", "Pegasus Kid (neck)"], ["Next", "Fukuoka, 7/18"]], "body": [["h", "The Samoans Leave a Mark"], ["p", "Summer Crush '91 reached the Sun Plaza Hall in Hiroshima on Sunday night, and the tour's sixth stop ended the way the last three have: with the Samoans standing over a New Japan champion."], ["p", "Riki Chōshu came out for the main event without Shinya Hashimoto, who wasn't in the building. Hiroyoshi Tenzan stepped in beside Chōshu and Junji Hirata against Samu, Kokina and Tarzan Goto. For fifteen minutes it was a fight more than a match. The end came when Hirata had Samu reeling and Afa came over the rail and hit him from behind. The referee threw it out and gave the win to Chōshu's team, but that didn't stop anybody. Samu and Kokina put the boots to Hirata until the young lions dragged them away."], ["p", "Chōshu helped his tag champion to his feet and took the microphone. The Samoans have been coming for him since Nagoya, he said, and now they've come for Hirata. If they want the tag belts at Sumo Hall, they go through him and the champions every night until July 30."], ["p", "The match of the night came one bout earlier. Keiji Mutoh and Masahiro Chono went eighteen minutes with Tatsumi Fujinami and Shiro Koshinaka before Mutoh climbed to the top and finished Koshinaka with the moonsault. Chono stood on the apron and pointed at the crowd: Sumo Hall is two weeks away."], ["p", "Pegasus Kid won his rematch with Osamu Kido, who beat him in Nagoya, with a diving headbutt at 17:36. It cost him. Kid landed badly earlier in the match and left holding his neck, and he's expected to miss time. His IWGP Junior Heavyweight Title match with Jushin Liger at Sumo Hall is now in question."], ["p", "Bam Bam Bigelow pinned Keith Hart with the Greetings from Asbury Park, Mil Mascaras splashed Norio Honaga to win the six-man for the lucha trio with Dos Caras and Gran Hamada, and Hiro Saito and Kengo Kimura beat Tony Halme and Jeff Gaylord when Saito suplexed Halme. That's four straight losses for Halme on the tour, and the Hiroshima crowd let him hear it. El Samurai beat Akira Nogami in the opener."], ["p", "The tour moves to Fukuoka on Thursday."]]}, "njpw-observer-hiroshima-0714": {"p": "njpw", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-14", "region": "Japan Report", "kicker": "New Japan · Hiroshima · 7/14", "title": "Observer: Hiroshima", "dek": "Mutoh & Chono steal the show again, Hashimoto no-shows, and Pegasus Kid's neck puts the Sumo Hall junior title match in doubt.", "factTitle": "Match observations", "facts": [["Show", "Hiroshima, 7/14"], ["Venue", "Sun Plaza Hall"], ["Attendance", "TBD"], ["Gate", "TBD"], ["Card", "**1/4"], ["Match of the night", "Mutoh & Chono d. Fujinami & Koshinaka, ****"]], "body": [["p", "Night six of Summer Crush ran on the same Sunday as the Great American Bash and WrestleFest, and in Hiroshima it rated **1/4. The house number wasn't available at press time. The building holds 2,000."], ["p", "Two stories, and neither is good news for the office. First, Shinya Hashimoto no-showed. He was booked in the main event beside Chōshu and Hirata, and Hiroyoshi Tenzan was moved up to take his spot. Nobody has said why Hashimoto wasn't there. He's half of the tag champions and the whole back half of the tour runs through the tag title, with the Samoans getting a title match at Sumo Hall, so this needs an answer before Sapporo on 7/19, where Hashimoto and Hirata defend against Hase and Sasaki on TV."], ["p", "Second, Pegasus Kid hurt his neck in the Kido match and the early word is he'll miss about eight shows. New Japan only has five left on the tour: Fukuoka 7/18, Sapporo 7/19, Sendai 7/22, Morioka 7/29 and Sumo Hall 7/30. That puts the Liger vs. Kid IWGP Junior Title match at Sumo Hall in real danger, and the plan for that match was for Kid to win the belt. If he's out, the office has to decide whether to wait, change the challenger, or change the finish."], ["p", "El Samurai pinned Akira Nogami with an inverted swinging DDT in 10:06. *1/2. Fine opener."], ["p", "Hiro Saito & Kengo Kimura beat Tony Halme & Jeff Gaylord in 10:14 when Saito pinned Halme with a back suplex. **. Halme is 0–4 now and the crowds are getting on him, which appears to be the point."], ["p", "Mil Mascaras, Dos Caras & Gran Hamada beat Mando Guerrero, Norio Honaga & Kuniaki Kobayashi in 15:44 when Mascaras pinned Honaga with the flying bodypress. ***. Exactly what you'd expect from the lucha six-man. Mascaras still gets a reaction everywhere."], ["p", "Pegasus Kid pinned Osamu Kido with the diving headbutt in 17:36. **1/4. This was supposed to be the payback for Kido beating Kid in Nagoya, and it went longer than it needed to. Kid got hurt somewhere in the middle and the second half was slower because of it."], ["p", "Bam Bam Bigelow & Corporal Kirchner beat Jim Neidhart & Keith Hart in 12:11 when Bigelow pinned Keith with the Greetings from Asbury Park. *3/4."], ["p", "Keiji Mutoh & Masahiro Chono beat Tatsumi Fujinami & Shiro Koshinaka in 18:38 when Mutoh pinned Koshinaka with the moonsault. ****. Best match of the night by a mile and the third straight great tag for Mutoh and Chono on this tour (***3/4 in Nagoya, ***3/4 in Abashiri). Fujinami and Koshinaka were terrific in there too. Chono is being built as the hottest challenger in the company two weeks before he gets Chōshu at Sumo Hall, and so far it's working."], ["p", "Riki Chōshu, Junji Hirata & Hiroyoshi Tenzan beat the Samoans & Tarzan Goto in 15:07 when Hirata won by DQ over Samu after Afa interfered. *. Long, slow, and the Samoans aren't carrying anyone yet. The angle afterward, with the Samoans beating down Hirata and Chōshu promising they go through him and the champions every night until Sumo Hall, did more for the tag title match than the bout did. That's the second straight Afa run-in on Hirata (Abashiri, now Hiroshima)."], ["p", "Bottom line: a weak card with one great match, a no-show from a champion, and an injury to the guy who's supposed to win a title at the biggest show of the summer. The next two shows (Fukuoka and the Sapporo TV) will show how the office plans to cover both."]]}, "njpw-diary-pegasus-0714": {"p": "njpw", "series": "diary", "by": "Pegasus Kid", "date": "1991-07-14", "place": "Business hotel near Hiroshima Station", "kicker": "From the Road · Hiroshima, 7/14", "title": "Ice in a Towel", "dek": "Pegasus Kid beats Osamu Kido, feels something go in his neck, and does the math on Sumo Hall.", "factTitle": "The Night", "facts": [["Show", "NJPW Summer Crush '91, Night 6"], ["Match", "Pegasus Kid d. Osamu Kido"], ["Finish", "Diving headbutt, 17:36"], ["Rating", "**1/4"], ["Injury", "Neck, out about 8 cards"]], "body": [["p", "I'm writing this lying flat on the floor of the hotel room, because it's the only way my neck doesn't hurt. Ice in a towel under it. The bed's too soft."], ["p", "Kido beat me in Nagoya and I wanted it back. He's a hard man to wrestle. Everything he does is tight, and he doesn't give you anything you haven't earned. About eight minutes in he caught me with a suplex and I landed on the back of my head and neck, and I felt something go. Not a pop. More like somebody turned a screw."], ["p", "I finished the match. I don't know how good it was. I stopped thinking about the match and started thinking about getting to the finish. Got him with the headbutt off the top at seventeen minutes and change. Kido shook my hand after and asked if I was all right. I said yes. I wasn't."], ["p", "The doctor at the building said rest. The office says maybe eight shows. I did the math in the bus on the way here. There are five shows left on this tour. Sumo Hall is one of them. Liger and me at Sumo Hall is the reason I came back to Japan this summer."], ["p", "I've worked hurt before. Everybody here has. But a neck is a neck, and I'm twenty-four. My dad called the hotel tonight and I didn't tell him."], ["p", "Downstairs, Mutoh and Chono and the boys were eating and laughing about their match, and they should be. It was the best thing on the show. I listened to them through the floor for a while and then I fell asleep on the ice."]]}, "njpw-pegasus-off-tour": {"p": "njpw", "news": 1, "region": "Japan Report", "by": "Newsletter staff", "date": "1991-07-15", "kicker": "New Japan · Injury", "title": "Pegasus Kid Is Off the Tour", "dek": "The neck injury from Hiroshima ends Pegasus Kid's summer. Jushin Liger's Sumo Hall title defense needs a new challenger.", "factTitle": "The Damage", "facts": [["Injured", "Hiroshima, 7/14, vs. Osamu Kido"], ["Injury", "Neck"], ["Misses", "Fukuoka, Sapporo TV, Sendai, Morioka, Sumo Hall"], ["Was booked for", "IWGP Junior Title vs. Liger, Sumo Hall 7/30"], ["Replacement", "El Samurai"]], "body": [["p", "New Japan has taken Pegasus Kid off the rest of Summer Crush '91. Kid hurt his neck in his win over Osamu Kido in Hiroshima on Sunday, and the office decided not to risk him on the five dates left on the tour."], ["p", "That ends the IWGP Junior Heavyweight Title match between Kid and champion Jushin Liger that was announced for the Sumo Hall finale on July 30. Kid was supposed to be the full-time junior who took the belt from the champion who spends half his time in WCW. Now New Japan has a title match on its biggest show of the summer and no challenger."], ["p", "The obvious candidates are already on the tour. El Samurai has lost to Liger once this month but has been the most consistent junior on the cards. Gran Hamada confronted Liger on opening night at Korakuen and has never had his match. Norio Honaga and Kuniaki Kobayashi have both been around the junior division for years. Nobody has been named yet."], ["p", "Kid also had matches booked in Fukuoka on Thursday, on the Sapporo TV taping on Friday, where he was set to face El Samurai again, and in Sendai against Hamada. Those spots will be filled from the undercard."], ["p", "Kid is also Chris Benoit of the Power Pro academy in Canada, and he's expected to rest at home before anyone books him again."]]}, "njpw-samurai-gets-liger": {"p": "njpw", "news": 1, "region": "Japan Report", "by": "Newsletter staff", "date": "1991-07-15", "kicker": "New Japan · IWGP Junior Heavyweight Title", "title": "El Samurai Gets His Rematch", "dek": "With Pegasus Kid off the tour, El Samurai steps in to challenge Jushin Liger for the IWGP Junior Heavyweight Title at Sumo Hall on July 30.", "factTitle": "Sumo Hall, July 30", "facts": [["Title", "IWGP Junior Heavyweight"], ["Champion", "Jushin Liger"], ["Challenger", "El Samurai"], ["Last meeting", "Liger d. Samurai (moonsault), Niigata 7/5, ***3/4"], ["Replaces", "Pegasus Kid (neck)"]], "body": [["p", "New Japan has named El Samurai as Jushin Liger's challenger for the IWGP Junior Heavyweight Title at the Sumo Hall finale of Summer Crush '91 on July 30. Samurai replaces Pegasus Kid, who hurt his neck in Hiroshima and is off the rest of the tour."], ["p", "It's a rematch. Liger and Samurai met for the title in Niigata on July 5, the second night of the tour, and Liger won with the moonsault in a match that rated ***3/4. Samurai is a New Japan lifer and the most consistent junior on these cards, and unlike Liger he's been on every stop. That's the story the office is likely to tell: the full-timer against the champion who keeps flying back to WCW."], ["p", "Liger's availability is still the catch. He's booked in WCW and in CMLL's Acapulco show on 7/17, and he's expected back in New Japan for Morioka on 7/29 and Sumo Hall the next night. If WCW keeps him off its late-July dates, the match goes ahead."], ["p", "The rest of the Sumo Hall card is set: Riki Chōshu defends the IWGP Heavyweight Title against Masahiro Chono, and the tag champions face the Samoans."]]}});

CONTRACTS.njpw = {"basis": "Per tour", "unit": "per tour", "revenue": "Summer Crush '91: $368,600 from the first five nights (about $74K a night). Eleven dates puts the full tour at roughly $940K.", "target": "Tour payroll at about 35% of the tour gate.", "how": "One flat fee per tour, paid at the end of the tour. Wrestlers who work only part of the tour (WCW, WWF and TWA crossovers) are paid that share for the nights they work. Fees are for the full 11-date Summer Crush tour. Antonio Inoki is the founder and is not on the scale. Managers and announcers are on the same scale. The TV Asahi booth is paid by the network, not the promotion.", "classes": [], "rows": [["A", "Riki Chōshu", 28000, "IWGP Heavyweight Champion"], ["A", "Tatsumi Fujinami", 22000, ""], ["A", "Big Van Vader", 20000, "Also WCW"], ["A", "Bam Bam Bigelow", 18000, "Also TWA"], ["A", "Keiji Mutoh", 18000, ""], ["B", "Masahiro Chono", 16000, ""], ["B", "Shinya Hashimoto", 16000, "IWGP Tag Champion"], ["B", "Jushin Liger", 16000, "IWGP Junior Champion, also WCW"], ["B", "Sting 1992", 15000, "Also WCW"], ["B", "Mil Mascaras", 10000, ""], ["B", "Tiger Jeet Singh", 10000, ""], ["B", "Pegasus Kid", 10000, ""], ["B", "Hiroshi Hase", 10000, ""], ["B", "Scott Norton", 10000, ""], ["C", "Junji Hirata", 8000, "IWGP Tag Champion"], ["C", "Kensuke Sasaki", 8000, ""], ["C", "Shiro Koshinaka", 8000, ""], ["C", "Kim Duk", 8000, ""], ["C", "Brian Pillman", 8000, "Also WCW"], ["C", "El Gigante", 8000, "Also WCW"], ["C", "Jim Neidhart", 7000, ""], ["C", "Kengo Kimura", 6000, ""], ["C", "Osamu Kido", 6000, ""], ["C", "Hiro Saito", 6000, ""], ["C", "El Samurai", 6000, ""], ["C", "Gran Hamada", 6000, "Also ASW"], ["C", "The Blue Blazer", 6000, "Owen Hart, also WWF"], ["C", "Mike Rotunda", 6000, "IRS in the WWF"], ["C", "Dos Caras", 6000, ""], ["D", "Masashi Aoyagi", 5000, ""], ["D", "Tarzan Goto", 5000, ""], ["D", "Norio Honaga", 5000, ""], ["D", "Akira Nogami", 5000, ""], ["D", "Kuniaki Kobayashi", 5000, ""], ["D", "Tony Halme", 5000, ""], ["D", "Ken Patera", 5000, ""], ["D", "Kokina", 5000, "The Samoans"], ["D", "Samu", 5000, "The Samoans"], ["D", "Mando Guerrero", 4000, ""], ["D", "Keith Hart", 4000, ""], ["D", "Corporal Kirchner", 4000, ""], ["E", "Hiroyoshi Tenzan", 3000, "Young lion"], ["E", "Jeff Gaylord", 3000, ""], ["E", "Savio Vega", 3000, ""], ["O", "TBD: ring announcer", 3000, "Name to be set"]], "total": 391000, "check": "Full-tour fees total $391,000: about 42% of a $940K tour before part-timers are prorated. Vader, Bigelow, Liger, Sting, Pillman, El Gigante, the Blue Blazer and Rotunda all miss dates, which brings it close to 35%."};

