BANNER_SVG.njpw = "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 1440 360\" role=\"img\" aria-label=\"New Japan Pro-Wrestling. Tokyo, Japan. Korakuen Hall, Sumo Hall, nationwide.\" style=\"display:block;width:100%;height:auto;background:#000000\"><rect width=\"1440\" height=\"360\" fill=\"#000000\"/><rect width=\"1440\" height=\"10\" fill=\"#E0150B\"/><rect y=\"350\" width=\"1440\" height=\"10\" fill=\"#E0150B\"/><rect y=\"10\" width=\"1440\" height=\"3\" fill=\"#FFD810\"/><rect y=\"347\" width=\"1440\" height=\"3\" fill=\"#FFD810\"/><rect y=\"118\" width=\"1440\" height=\"4\" fill=\"#1F1F1F\"/><rect y=\"178\" width=\"1440\" height=\"4\" fill=\"#1F1F1F\"/><rect y=\"238\" width=\"1440\" height=\"4\" fill=\"#1F1F1F\"/><image href=\"data:image/svg+xml;base64,\" x=\"120\" y=\"49.0\" width=\"264\" height=\"262\" preserveAspectRatio=\"xMidYMid meet\"/><g><text x=\"472\" y=\"84\" font-family=\"Oswald,'Roboto Condensed','Arial Narrow',sans-serif\" font-weight=\"600\" font-size=\"20\" letter-spacing=\"7\" fill=\"#A8A8A8\">TOKYO, JAPAN</text><text x=\"472\" y=\"190\" font-family=\"Anton,Impact,'Arial Narrow',sans-serif\" font-size=\"108\" letter-spacing=\"2\" fill=\"#FFFFFF\">NEW JAPAN</text><text x=\"472\" y=\"258\" font-family=\"Anton,Impact,'Arial Narrow',sans-serif\" font-size=\"54\" letter-spacing=\"5\" fill=\"#FFD810\">PRO-WRESTLING</text><g transform=\"translate(472 278)\"><polygon points=\"12,2 15.09,8.26 22,9.27 17,14.14 18.18,21.02 12,17.77 5.82,21.02 7,14.14 2,9.27 8.91,8.26\" fill=\"#FFD810\" stroke=\"#E0150B\" stroke-width=\"1.3\"/></g><g transform=\"translate(504 278)\"><polygon points=\"12,2 15.09,8.26 22,9.27 17,14.14 18.18,21.02 12,17.77 5.82,21.02 7,14.14 2,9.27 8.91,8.26\" fill=\"#FFD810\" stroke=\"#E0150B\" stroke-width=\"1.3\"/></g><g transform=\"translate(536 278)\"><polygon points=\"12,2 15.09,8.26 22,9.27 17,14.14 18.18,21.02 12,17.77 5.82,21.02 7,14.14 2,9.27 8.91,8.26\" fill=\"#FFD810\" stroke=\"#E0150B\" stroke-width=\"1.3\"/></g><text x=\"584\" y=\"298\" font-family=\"Oswald,'Roboto Condensed','Arial Narrow',sans-serif\" font-weight=\"500\" font-size=\"20\" letter-spacing=\"5\" fill=\"#D4D4D4\">KORAKUEN HALL · SUMO HALL · NATIONWIDE</text></g><text x=\"1400\" y=\"330\" text-anchor=\"end\" font-family=\"Oswald,'Roboto Condensed','Arial Narrow',sans-serif\" font-weight=\"500\" font-size=\"14\" letter-spacing=\"4\" fill=\"#8C8C8C\">TNM WORLD WRESTLING REPORT</text></svg>";
